from sympy import factorint

def find_spec_prod_part(n, com):
    if n < 2:
        return "Invalid input"
    if len(factorint(n)) == 1:
        return "It is a prime number"

    def score(partition):
        return sum(factor ** count for factor, count in partition) * len(partition)

    def partition(n, i=2, acc=None):
        if acc is None:
            acc = []
        if n == 1:
            yield acc + [1]
        elif n < 1:
            pass
        else:
            for k in range(n // i, 0, -1):
                yield from partition(n // k, i + 1, acc + [k])

    best_partition = None
    best_score = None

    for p in partition(n):
        p.sort(reverse=True)
        current_score = score(p)
        if com == 'max':
            if best_score is None or current_score > best_score:
                best_partition = p
                best_score = current_score
        elif com == 'min':
            if best_score is None or current_score < best_score:
                best_partition = p
                best_score = current_score

    return [best_partition, best_score]
